const query = ($('Webhook').first().json.body?.message || '').toLowerCase();
const list = $json.data || [];

let matched = list.filter(d => 
  d.nama.toLowerCase().includes(query) || 
  d.grup.toLowerCase().includes(query) || 
  d.idn.toLowerCase().includes(query)
);

if (matched.length === 0) {
  matched = [list[0]];
}

const doa = matched[0];
let content = `🤲 **${doa.nama}**\n📂 *Kategori: ${doa.grup}*\n\n> ### ${doa.ar}\n\n`;
if (doa.tr) content += `*Transliterasi:*\n**"${doa.tr}"**\n\n`;
content += `*Artinya:*\n> "${doa.idn}"\n\n`;
if (doa.tentang) content += `📚 *Keterangan:* ${doa.tentang}\n`;

const chips = [
  '🌅 Dzikir Pagi & Petang',
  '🛌 Doa Sebelum & Bangun Tidur',
  '🚗 Doa Naik Kendaraan & Safar',
  '🤲 Doa Kebaikan Dunia Akhirat'
];

return { json: { content, chips } };
